def canonicalize_service(service):
    """Normalize AI service labels so one enquiry updates the right open lead."""
    value = " ".join(str(service or "General Enquiry").strip().lower().split())

    aliases = {
        "landscaping": "Landscaping",
        "landscaping service": "Landscaping",
        "landscaping services": "Landscaping",
        "fumigation": "Fumigation",
        "fumigation service": "Fumigation",
        "fumigation services": "Fumigation",
        "cleaning": "Cleaning Services",
        "cleaning service": "Cleaning Services",
        "cleaning services": "Cleaning Services",
        "car wash": "Car Wash",
        "carwash": "Car Wash",
        "construction": "Construction",
        "construction services": "Construction",
        "agro": "Agro Services",
        "agro services": "Agro Services",
        "agriculture": "Agro Services",
        "website": "Website Development",
        "website development": "Website Development",
        "web development": "Website Development",
        "whatsapp ai assistant": "WhatsApp AI Assistant",
        "ai business assistant": "WhatsApp AI Assistant",
        "career assist": "Career Assist",
        "scholarship search": "Scholarship Search",
        "cv and cover letter": "CV & Cover Letter",
        "cv & cover letter": "CV & Cover Letter",
        "business services": "Business Services",
        "business registration": "Business Registration",
        "graphic design": "Graphic Design",
        "branding": "Branding",
        "social media": "Social Media Management",
        "social media management": "Social Media Management",
        "photo restoration": "Photo Restoration",
        "website development service": "Website Development",
        "website development services": "Website Development",
        "human handover": "General Enquiry",
        "human support": "General Enquiry",
        "human assistance": "General Enquiry",
        "handover": "General Enquiry",
        "general": "General Enquiry",
        "general enquiry": "General Enquiry",
        "general inquiry": "General Enquiry",
    }

    return aliases.get(value, str(service or "General Enquiry").strip() or "General Enquiry")


def get_latest_open_lead_service(customer_number):
    """
    Keep an explicit human takeover attached to the customer's current service
    when possible. "Human Handover" is a workflow state, not a service category.
    """
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT service
                FROM leads
                WHERE customer_number = %s
                  AND status IN ('NEW', 'CONTACTED')
                  AND merged_into_lead_id IS NULL
                ORDER BY updated_at DESC, created_at DESC
                LIMIT 1
                """,
                (customer_number,)
            )
            row = cur.fetchone()

    if row and row[0]:
        return canonicalize_service(row[0])
    return "General Enquiry"


def create_or_update_lead(
    customer_number,
    customer_name,
    service,
    summary,
    handover_reason
):
    service = canonicalize_service(service)

    with get_db() as conn:
        with conn.cursor() as cur:

            cur.execute(
                """
                SELECT id, service
                FROM leads
                WHERE customer_number = %s
                  AND status IN ('NEW', 'CONTACTED')
                  AND merged_into_lead_id IS NULL
                ORDER BY updated_at DESC, created_at DESC
                """,
                (customer_number,)
            )

            existing = None
            for candidate_id, candidate_service in cur.fetchall():
                if canonicalize_service(candidate_service).casefold() == service.casefold():
                    existing = (candidate_id,)
                    break

            if existing:
                lead_id = existing[0]

                cur.execute(
                    """
                    UPDATE leads
                    SET customer_name = COALESCE(
                            NULLIF(%s, ''),
                            customer_name
                        ),
                        service = %s,
                        summary = %s,
                        handover_reason = %s,
                        updated_at = NOW()
                    WHERE id = %s
                    """,
                    (
                        customer_name,
                        service,
                        summary,
                        handover_reason,
                        lead_id
                    )
                )

                _activity_insert(
                    cur,
                    lead_id,
                    "AI_UPDATE",
                    "Lead details refreshed from the WhatsApp conversation.",
                )

                print(
                    f"LEAD UPDATED: {lead_id}",
                    flush=True
                )

            else:
                cur.execute(
                    """
                    INSERT INTO leads (
                        customer_number,
                        customer_name,
                        service,
                        summary,
                        handover_reason
                    )
                    VALUES (%s, %s, %s, %s, %s)
                    RETURNING id
                    """,
                    (
                        customer_number,
                        customer_name,
                        service,
                        summary,
                        handover_reason
                    )
                )

                lead_id = cur.fetchone()[0]

                _activity_insert(
                    cur,
                    lead_id,
                    "LEAD_CREATED",
                    f"{service} lead created from WhatsApp.",
                )

                print(
                    f"NEW LEAD CREATED: {lead_id}",
                    flush=True
                )

        conn.commit()

    return lead_id, existing is None


def record_lead_notification(lead_id, status, error=None):
    """Persist notification delivery state without storing API secrets."""
    try:
        with get_db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO lead_notification_status
                        (lead_id, status, attempts, last_error, updated_at)
                    VALUES (%s, %s, 1, %s, NOW())
                    ON CONFLICT (lead_id) DO UPDATE SET
                        status=EXCLUDED.status,
                        attempts=lead_notification_status.attempts + 1,
                        last_error=EXCLUDED.last_error,
                        updated_at=NOW()
                    """,
                    (lead_id, status, error)
                )
            conn.commit()
    except Exception as tracking_error:
        print(
            f"Lead notification tracking error: {type(tracking_error).__name__}",
            flush=True
        )


def send_new_lead_email(
    lead_id,
    customer_name,
    customer_number,
    service,
    summary,
    handover_reason
):
    if not BREVO_API_KEY or not NOTIFICATION_EMAIL or not BREVO_SENDER_EMAIL:
        print(
            "Lead email skipped: Brevo API settings are not fully configured.",
            flush=True
        )
        record_lead_notification(lead_id, "FAILED", "Brevo configuration incomplete")
        return False

    display_name = customer_name or "Not provided"
    subject = f"New IBROWS Lead #{lead_id}: {service}"
    body = f"""A new qualified lead has been captured by the IBROWS AI Business Assistant.

Lead ID: {lead_id}
Customer: {display_name}
WhatsApp: +{customer_number}
Service: {service}

Lead summary:
{summary}

Human follow-up reason:
{handover_reason}

Lead dashboard:
{LEAD_DASHBOARD_URL}

IBROWS Enterprise
Kupanga zofanana, mosiyana
"""

    payload = {
        "sender": {
            "name": BREVO_SENDER_NAME,
            "email": BREVO_SENDER_EMAIL,
        },
        "to": [
            {"email": NOTIFICATION_EMAIL}
        ],
        "subject": subject,
        "textContent": body,
    }

    try:
        response = requests.post(
            "https://api.brevo.com/v3/smtp/email",
            headers={
                "accept": "application/json",
                "api-key": BREVO_API_KEY,
                "content-type": "application/json",
            },
            json=payload,
            timeout=8,
        )

        if 200 <= response.status_code < 300:
            record_lead_notification(lead_id, "SENT")
            print(
                f"NEW LEAD EMAIL SENT: {lead_id}",
                flush=True
            )
            return True

        error_label = f"Brevo HTTP {response.status_code}"
        record_lead_notification(lead_id, "FAILED", error_label)
        print(
            f"Lead email error for lead {lead_id}: {error_label}",
            flush=True
        )
        return False

    except requests.RequestException as error:
        error_label = type(error).__name__
        record_lead_notification(lead_id, "FAILED", error_label)
        print(
            f"Lead email error for lead {lead_id}: {error_label}",
            flush=True
        )
        return False



def claim_due_follow_up_reminders(limit=20):
    """
    Atomically claim due follow-ups. Stale claims older than 15 minutes are
    recoverable so a crashed worker cannot permanently suppress a reminder.
    """
    limit = max(1, min(int(limit), 50))
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT
                    id,
                    customer_number,
                    customer_name,
                    service,
                    summary,
                    priority,
                    follow_up_at
                FROM leads
                WHERE status <> 'CLOSED'
                  AND follow_up_at IS NOT NULL
                  AND follow_up_at <= NOW()
                  AND follow_up_notified_at IS NULL
                  AND (
                        follow_up_notification_claimed_at IS NULL
                        OR follow_up_notification_claimed_at
                           < NOW() - INTERVAL '15 minutes'
                  )
                ORDER BY follow_up_at ASC
                LIMIT %s
                FOR UPDATE SKIP LOCKED
                """,
                (limit,)
            )
            rows = cur.fetchall()

            for row in rows:
                cur.execute(
                    """
                    UPDATE leads
                    SET follow_up_notification_claimed_at = NOW(),
                        follow_up_notification_error = NULL
                    WHERE id = %s
                      AND follow_up_notified_at IS NULL
                      AND merged_into_lead_id IS NULL
                    """,
                    (row[0],)
                )
        conn.commit()

    return [
        {
            "id": row[0],
            "customer_number": row[1],
            "customer_name": row[2],
            "service": canonicalize_service(row[3]),
            "summary": row[4],
            "priority": row[5] or "NORMAL",
            "follow_up_at": row[6],
        }
        for row in rows
    ]


