QUOTE_STATUSES = {
    "NOT_STARTED": "Not started",
    "DRAFT": "Draft",
    "SENT": "Sent",
    "ACCEPTED": "Accepted",
    "DECLINED": "Declined",
}
SUPPORTED_CRM_CURRENCIES = {"MWK", "USD", "ZAR", "EUR", "GBP"}


def _crm_money_value(raw_value):
    value = str(raw_value or "").replace(",", "").strip()
    if not value:
        return None
    try:
        amount = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError("Invalid estimated value.")
    if amount < 0 or amount > Decimal("999999999999.99"):
        raise ValueError("Estimated value outside allowed range.")
    return amount.quantize(Decimal("0.01"))


def _crm_currency(raw_currency):
    currency = str(raw_currency or "MWK").strip().upper()
    if currency not in SUPPORTED_CRM_CURRENCIES:
        raise ValueError("Invalid currency.")
    return currency


def _crm_quote_status(raw_status):
    status = str(raw_status or "NOT_STARTED").strip().upper()
    if status not in QUOTE_STATUSES:
        raise ValueError("Invalid quote status.")
    return status


def _activity_insert(cur, lead_id, activity_type, description):
    description = " ".join(str(description or "").split()).strip()
    if not description:
        return
    cur.execute(
        """
        INSERT INTO lead_activity (lead_id, activity_type, description)
        VALUES (%s, %s, %s)
        """,
        (lead_id, str(activity_type or "UPDATE")[:60], description[:1000])
    )




PAYMENT_METHODS = {
    "CASH": "Cash",
    "BANK_TRANSFER": "Bank transfer",
    "MOBILE_MONEY": "Mobile money",
    "CARD": "Card",
    "OTHER": "Other",
}


def _crm_payment_amount(raw_value):
    value = str(raw_value or "").replace(",", "").strip()
    if not value:
        return None
    try:
        amount = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError("Invalid payment amount.")
    if amount <= 0 or amount > Decimal("999999999999.99"):
        raise ValueError("Payment amount outside allowed range.")
    return amount.quantize(Decimal("0.01"))


def _crm_payment_method(raw_method):
    method = str(raw_method or "OTHER").strip().upper()
    if method not in PAYMENT_METHODS:
        raise ValueError("Invalid payment method.")
    return method



BUSINESS_DOCUMENT_TYPES = {
    "quotation": "Quotation",
    "invoice": "Invoice",
    "receipt": "Receipt",
}

BUSINESS_DOCUMENT_PREFIXES = {
    "quotation": "Q",
    "invoice": "I",
    "receipt": "R",
}
BUSINESS_QUOTATION_VALID_DAYS = 7
BUSINESS_INVOICE_DUE_DAYS = 7


def get_or_create_business_document_record(doc_type, lead_id, payment_id=None):
    """
    Allocate a permanent professional number once, then reuse it forever.
    Quotations/invoices are one number per lead; receipts are one number
    per individual payment transaction.
    """
    doc_type = str(doc_type or "").strip().lower()
    if doc_type not in BUSINESS_DOCUMENT_TYPES:
        raise ValueError("Unsupported document type.")

    if doc_type == "receipt":
        if not payment_id:
            raise ValueError("Receipt requires a payment.")
    else:
        payment_id = None

    with get_db() as conn:
        with conn.cursor() as cur:
            if doc_type == "receipt":
                cur.execute(
                    """
                    SELECT id, document_number, issued_at
                    FROM business_documents
                    WHERE doc_type = 'receipt'
                      AND payment_id = %s
                    LIMIT 1
                    FOR UPDATE
                    """,
                    (payment_id,)
                )
            else:
                cur.execute(
                    """
                    SELECT id, document_number, issued_at
                    FROM business_documents
                    WHERE lead_id = %s
                      AND doc_type = %s
                    LIMIT 1
                    FOR UPDATE
                    """,
                    (lead_id, doc_type)
                )

            existing = cur.fetchone()
            if existing:
                return {
                    "id": existing[0],
                    "document_number": existing[1],
                    "issued_at": existing[2],
                }

            year = datetime.now(ADMIN_TIMEZONE).year
            cur.execute(
                """
                INSERT INTO business_document_sequences (
                    document_year, doc_type, last_number
                )
                VALUES (%s, %s, 0)
                ON CONFLICT (document_year, doc_type) DO NOTHING
                """,
                (year, doc_type)
            )
            cur.execute(
                """
                SELECT last_number
                FROM business_document_sequences
                WHERE document_year = %s
                  AND doc_type = %s
                FOR UPDATE
                """,
                (year, doc_type)
            )
            current = cur.fetchone()
            if not current:
                raise RuntimeError("Document sequence unavailable.")

            next_number = int(current[0]) + 1
            cur.execute(
                """
                UPDATE business_document_sequences
                SET last_number = %s
                WHERE document_year = %s
                  AND doc_type = %s
                """,
                (next_number, year, doc_type)
            )

            prefix = BUSINESS_DOCUMENT_PREFIXES[doc_type]
            document_number = f"IB-{prefix}-{year}-{next_number:04d}"

            cur.execute(
                """
                INSERT INTO business_documents (
                    lead_id, payment_id, doc_type, document_number
                )
                VALUES (%s, %s, %s, %s)
                RETURNING id, document_number, issued_at
                """,
                (lead_id, payment_id, doc_type, document_number)
            )
            created = cur.fetchone()

            _activity_insert(
                cur,
                lead_id,
                "DOCUMENT_CREATED",
                (
                    f"{BUSINESS_DOCUMENT_TYPES[doc_type]} "
                    f"{created[1]} generated."
                ),
            )

        conn.commit()

    print(
        f"BUSINESS DOCUMENT NUMBER ALLOCATED: "
        f"lead={lead_id} type={doc_type} number={created[1]}",
        flush=True,
    )
    return {
        "id": created[0],
        "document_number": created[1],
        "issued_at": created[2],
    }



def get_customer_business_documents(customer_number):
    """
    Return the customer's permanent document registry, including documents
    attached to merged historical lead records.
    """
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT
                    d.id,
                    d.lead_id,
                    d.payment_id,
                    d.doc_type,
                    d.document_number,
                    d.issued_at,
                    d.last_sent_at,
                    COALESCE(d.send_count, 0),
                    l.service,
                    l.merged_into_lead_id
                FROM business_documents d
                JOIN leads l ON l.id = d.lead_id
                WHERE l.customer_number = %s
                ORDER BY d.issued_at DESC, d.id DESC
                """,
                (customer_number,)
            )
            rows = cur.fetchall()

    documents = []
    for row in rows:
        doc_type = row[3]
        documents.append({
            "id": row[0],
            "lead_id": row[1],
            "payment_id": row[2],
            "doc_type": doc_type,
            "doc_type_label": BUSINESS_DOCUMENT_TYPES.get(
                doc_type,
                str(doc_type or "").replace("_", " ").title(),
            ),
            "document_number": row[4],
            "issued_at": row[5],
            "last_sent_at": row[6],
            "send_count": int(row[7] or 0),
            "service": canonicalize_service(row[8]),
            "merged_historical": row[9] is not None,
        })
    return documents



def get_latest_payment_by_lead(lead_ids):
    if not lead_ids:
        return {}

    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT DISTINCT ON (lead_id)
                    id, lead_id, amount, currency, payment_method,
                    reference, payment_note, received_at
                FROM lead_payments
                WHERE lead_id = ANY(%s)
                ORDER BY lead_id, received_at DESC, id DESC
                """,
                (list(lead_ids),)
            )
            rows = cur.fetchall()

    result = {}
    for row in rows:
        result[row[1]] = {
            "id": row[0],
            "lead_id": row[1],
            "amount": Decimal(row[2]),
            "currency": row[3],
            "payment_method": row[4],
            "reference": row[5] or "",
            "payment_note": row[6] or "",
            "received_at": row[7],
        }
    return result


def get_business_document_context(lead_id, payment_id=None):
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT
                    id, customer_number, customer_name, service, summary,
                    status, priority, estimated_value, value_currency,
                    quote_status, quote_reference, created_at, updated_at
                FROM leads
                WHERE id = %s
                  AND merged_into_lead_id IS NULL
                """,
                (lead_id,)
            )
            row = cur.fetchone()
            if not row:
                return None

            lead = {
                "id": row[0],
                "customer_number": row[1],
                "customer_name": row[2] or "WhatsApp Customer",
                "service": canonicalize_service(row[3]),
                "summary": row[4] or "",
                "status": row[5],
                "priority": row[6] or "NORMAL",
                "estimated_value": Decimal(row[7]) if row[7] is not None else None,
                "value_currency": row[8] or "MWK",
                "quote_status": row[9] or "NOT_STARTED",
                "quote_reference": row[10] or "",
                "created_at": row[11],
                "updated_at": row[12],
            }

            cur.execute(
                """
                SELECT
                    id, amount, currency, payment_method,
                    reference, payment_note, received_at
                FROM lead_payments
                WHERE lead_id = %s
                ORDER BY received_at ASC, id ASC
                """,
                (lead_id,)
            )
            payment_rows = cur.fetchall()

    payments = [
        {
            "id": p[0],
            "amount": Decimal(p[1]),
            "currency": p[2],
            "payment_method": p[3],
            "reference": p[4] or "",
            "payment_note": p[5] or "",
            "received_at": p[6],
        }
        for p in payment_rows
    ]

    selected_payment = None
    if payment_id is not None:
        for payment in payments:
            if payment["id"] == payment_id:
                selected_payment = payment
                break
        if selected_payment is None:
            return None
    elif payments:
        selected_payment = payments[-1]

    currency = lead["value_currency"]
    paid_total = sum(
        (p["amount"] for p in payments if p["currency"] == currency),
        Decimal("0"),
    )
    estimated = lead["estimated_value"]
    balance = None
    if estimated is not None:
        balance = max(estimated - paid_total, Decimal("0"))

    lead["payments"] = payments
    lead["selected_payment"] = selected_payment
    lead["paid_total"] = paid_total
    lead["balance"] = balance
    return lead


def _business_doc_reference(document_record):
    if not document_record or not document_record.get("document_number"):
        raise ValueError("Document number unavailable.")
    return document_record["document_number"]


def _business_pdf_money(amount, currency):
    if amount is None:
        return "-"
    return _format_crm_amount(Decimal(amount), currency)


def _business_pdf_wrap(text, size=10, bold=False, width=475):
    return _wrap_pdf_text_points(
        _pdf_normalize_text(text),
        size=size,
        bold=bold,
        max_points=width,
    )


def _business_pdf_build(doc_type, lead, payment_id=None, document_record=None):
    doc_type = str(doc_type or "").strip().lower()
    if doc_type not in BUSINESS_DOCUMENT_TYPES:
        raise ValueError("Unsupported document type.")

    if lead.get("estimated_value") is None and doc_type in {"quotation", "invoice"}:
        raise ValueError("A quotation/invoice requires an estimated value.")

    selected_payment = lead.get("selected_payment")
    if payment_id is not None and selected_payment and selected_payment["id"] != payment_id:
        selected_payment = next(
            (p for p in lead.get("payments", []) if p["id"] == payment_id),
            None,
        )
    if doc_type == "receipt" and not selected_payment:
        raise ValueError("No payment is available for this receipt.")

    if not document_record:
        raise ValueError("Document record is required.")

    reference = _business_doc_reference(document_record)
    issued_local = document_record["issued_at"].astimezone(ADMIN_TIMEZONE)
    currency = lead.get("value_currency") or "MWK"

    if doc_type == "receipt":
        if (
            lead.get("estimated_value") is not None
            and lead.get("balance") is not None
            and Decimal(lead.get("balance")) > 0
        ):
            title = "DEPOSIT RECEIPT"
        else:
            title = "PAYMENT RECEIPT"
        document_date = selected_payment["received_at"].astimezone(ADMIN_TIMEZONE)
    else:
        title = BUSINESS_DOCUMENT_TYPES[doc_type].upper()
        document_date = issued_local

    secondary_header = ""
    if doc_type == "quotation":
        valid_until = issued_local + timedelta(days=BUSINESS_QUOTATION_VALID_DAYS)
        secondary_header = (
            "Valid until: " + valid_until.strftime("%d %B %Y")
        )
    elif doc_type == "invoice":
        balance = lead.get("balance")
        balance = Decimal(balance) if balance is not None else Decimal("0")
        if balance <= 0:
            secondary_header = "Status: Paid in full"
        else:
            due_date = issued_local + timedelta(days=BUSINESS_INVOICE_DUE_DAYS)
            secondary_header = "Due: " + due_date.strftime("%d %B %Y")
    elif doc_type == "receipt":
        secondary_header = (
            "Payment date: " + document_date.strftime("%d %B %Y")
        )

    # First page only. Business documents are intentionally concise.
    commands = []

    # Header logo + document title.
    logo_w = 176.0
    logo_h = logo_w * (IBROWS_LOGO_JPEG_HEIGHT / IBROWS_LOGO_JPEG_WIDTH)
    commands.append(
        f"q {logo_w:g} 0 0 {logo_h:g} 42 {795-logo_h:g} cm /Logo Do Q"
    )
    commands.append("0.12 0.12 0.16 rg")
    commands.append(
        f"BT /F2 21 Tf 390 796 Td ({_pdf_escape(title)}) Tj ET"
    )
    commands.append(
        f"BT /F1 9 Tf 390 777 Td ({_pdf_escape('Document No: ' + reference)}) Tj ET"
    )
    commands.append(
        f"BT /F1 9 Tf 390 763 Td ({_pdf_escape('Date: ' + document_date.strftime('%d %B %Y'))}) Tj ET"
    )
    if secondary_header:
        commands.append(
            f"BT /F1 8.5 Tf 390 749 Td ({_pdf_escape(secondary_header)}) Tj ET"
        )

    # Purple brand rule.
    commands.append("0.39 0.08 0.35 RG 2 w 42 724 m 553 724 l S")
    commands.append("0 0 0 rg")

    # Business information.
    business_lines = [
        IBROWS_BUSINESS_NAME,
        IBROWS_BUSINESS_LOCATION,
        f"WhatsApp: {IBROWS_BUSINESS_WHATSAPP}",
        f"Email: {IBROWS_BUSINESS_EMAIL}",
        IBROWS_BUSINESS_TAGLINE,
    ]
    y = 704.0
    for idx, line in enumerate(business_lines):
        font = "F2" if idx == 0 else "F1"
        size = 10.5 if idx == 0 else 9
        commands.append(
            f"BT /{font} {size:g} Tf 42 {y:g} Td ({_pdf_escape(line)}) Tj ET"
        )
        y -= 14.0

    # Customer box.
    y = 620.0
    commands.append("0.96 0.96 0.97 rg 42 546 511 66 re f")
    commands.append("0 0 0 rg")
    commands.append("BT /F2 10 Tf 52 594 Td (CUSTOMER) Tj ET")
    customer_name = lead.get("customer_name") or "WhatsApp Customer"
    customer_number = "+" + str(lead.get("customer_number") or "").lstrip("+")
    commands.append(
        f"BT /F2 11 Tf 52 575 Td ({_pdf_escape(customer_name)}) Tj ET"
    )
    commands.append(
        f"BT /F1 9.5 Tf 52 559 Td ({_pdf_escape(customer_number)}) Tj ET"
    )

    # Service / description.
    y = 520.0
    commands.append("BT /F2 10 Tf 42 520 Td (SERVICE) Tj ET")
    commands.append(
        f"BT /F2 12 Tf 42 500 Td ({_pdf_escape(lead.get('service') or 'General Enquiry')}) Tj ET"
    )
    y = 482.0
    summary_lines = _business_pdf_wrap(
        lead.get("summary") or "Service requested through IBROWS Enterprise.",
        size=9.5,
        width=510,
    )[:6]
    for line in summary_lines:
        commands.append(
            f"BT /F1 9.5 Tf 42 {y:g} Td ({_pdf_escape(line)}) Tj ET"
        )
        y -= 13.0

    # Financial section.
    box_top = max(360.0, y - 15.0)
    row_y = box_top
    commands.append("0.39 0.08 0.35 rg")
    commands.append(f"42 {row_y:g} 511 26 re f")
    commands.append("1 1 1 rg")
    commands.append(
        f"BT /F2 10 Tf 52 {row_y+8:g} Td (FINANCIAL SUMMARY) Tj ET"
    )
    commands.append("0 0 0 rg")
    row_y -= 24.0

    rows = []
    if doc_type == "quotation":
        rows = [
            ("Quoted amount", _business_pdf_money(lead["estimated_value"], currency)),
            ("Quotation status", QUOTE_STATUSES.get(lead.get("quote_status"), "Not started")),
        ]
        if lead.get("quote_reference"):
            rows.append(("Customer reference", lead["quote_reference"]))
        rows.append(
            ("Validity", f"{BUSINESS_QUOTATION_VALID_DAYS} days from issue")
        )
    elif doc_type == "invoice":
        balance = Decimal(lead.get("balance") or 0)
        if balance <= 0:
            invoice_status = "Paid in full"
        elif Decimal(lead.get("paid_total") or 0) > 0:
            invoice_status = "Part paid"
        else:
            invoice_status = "Unpaid"

        rows = [
            ("Service value", _business_pdf_money(lead["estimated_value"], currency)),
            ("Payments received", _business_pdf_money(lead.get("paid_total", 0), currency)),
            ("Balance due", _business_pdf_money(lead.get("balance"), currency)),
            ("Invoice status", invoice_status),
        ]
        if lead.get("quote_reference"):
            rows.append(("Customer reference", lead["quote_reference"]))
    else:
        method_label = PAYMENT_METHODS.get(
            selected_payment.get("payment_method") or "OTHER",
            "Other",
        )
        rows = [
            ("Amount received", _business_pdf_money(selected_payment["amount"], selected_payment["currency"])),
            ("Payment method", method_label),
            ("Cumulative payments", _business_pdf_money(lead.get("paid_total", 0), currency)),
        ]
        if lead.get("estimated_value") is not None:
            remaining = Decimal(lead.get("balance") or 0)
            rows += [
                ("Service value", _business_pdf_money(lead["estimated_value"], currency)),
                ("Remaining balance", _business_pdf_money(lead.get("balance"), currency)),
                (
                    "Payment status",
                    "Paid in full" if remaining <= 0 else "Deposit / part payment",
                ),
            ]

    for label, value in rows:
        commands.append("0.94 0.94 0.95 RG 0.6 w")
        commands.append(f"42 {row_y:g} 511 24 re S")
        commands.append(
            f"BT /F1 9.5 Tf 52 {row_y+8:g} Td ({_pdf_escape(label)}) Tj ET"
        )
        commands.append(
            f"BT /F2 10 Tf 382 {row_y+8:g} Td ({_pdf_escape(str(value))}) Tj ET"
        )
        row_y -= 24.0

    if doc_type == "receipt" and selected_payment:
        if selected_payment.get("reference"):
            commands.append(
                f"BT /F1 9 Tf 42 {row_y-6:g} Td "
                f"({_pdf_escape('Payment reference: ' + selected_payment['reference'])}) Tj ET"
            )
            row_y -= 16.0
        if selected_payment.get("payment_note"):
            for line in _business_pdf_wrap(
                "Note: " + selected_payment["payment_note"],
                size=9,
                width=510,
            )[:3]:
                commands.append(
                    f"BT /F1 9 Tf 42 {row_y-6:g} Td ({_pdf_escape(line)}) Tj ET"
                )
                row_y -= 13.0

    # Footer.
    footer_y = 76
    commands.append("0.85 0.85 0.87 RG 0.8 w 42 96 m 553 96 l S")
    commands.append("0.35 0.35 0.38 rg")
    footer_text = (
        "Thank you for choosing IBROWS Enterprise."
        if doc_type == "receipt"
        else "Prepared by IBROWS Enterprise."
    )
    commands.append(
        f"BT /F2 9 Tf 42 {footer_y:g} Td ({_pdf_escape(footer_text)}) Tj ET"
    )
    commands.append(
        f"BT /F1 8 Tf 42 {footer_y-14:g} Td "
        f"({_pdf_escape(IBROWS_BUSINESS_TAGLINE + ' | ' + IBROWS_BUSINESS_EMAIL)}) Tj ET"
    )
    commands.append("0 0 0 rg")

    content = "\n".join(commands).encode("latin-1", "strict")
    logo_bytes = base64.b64decode(IBROWS_LOGO_JPEG_B64)

    objects = {
        1: b"<< /Type /Catalog /Pages 2 0 R >>",
        2: b"<< /Type /Pages /Kids [6 0 R] /Count 1 >>",
        3: b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
        4: b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>",
        5: (
            b"<< /Type /XObject /Subtype /Image "
            + f"/Width {IBROWS_LOGO_JPEG_WIDTH} /Height {IBROWS_LOGO_JPEG_HEIGHT} ".encode("ascii")
            + b"/ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode "
            + f"/Length {len(logo_bytes)} >>\nstream\n".encode("ascii")
            + logo_bytes
            + b"\nendstream"
        ),
        6: (
            b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] "
            b"/Resources << /Font << /F1 3 0 R /F2 4 0 R >> "
            b"/XObject << /Logo 5 0 R >> >> /Contents 7 0 R >>"
        ),
        7: (
            b"<< /Length "
            + str(len(content)).encode("ascii")
            + b" >>\nstream\n"
            + content
            + b"\nendstream"
        ),
    }

    out = bytearray(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n")
    max_id = max(objects)
    offsets = [0] * (max_id + 1)
    for obj_id in range(1, max_id + 1):
        offsets[obj_id] = len(out)
        out.extend(f"{obj_id} 0 obj\n".encode("ascii"))
        out.extend(objects[obj_id])
        out.extend(b"\nendobj\n")

    xref = len(out)
    out.extend(f"xref\n0 {max_id + 1}\n".encode("ascii"))
    out.extend(b"0000000000 65535 f \n")
    for obj_id in range(1, max_id + 1):
        out.extend(f"{offsets[obj_id]:010d} 00000 n \n".encode("ascii"))
    out.extend(
        f"trailer\n<< /Size {max_id + 1} /Root 1 0 R >>\n"
        f"startxref\n{xref}\n%%EOF".encode("ascii")
    )

    safe_name = re.sub(r"[^A-Za-z0-9_-]+", "_", lead.get("customer_name") or "Customer").strip("_")
    safe_title = re.sub(r"[^A-Za-z0-9_-]+", "_", title.title()).strip("_")
    filename = f"IBROWS_{safe_title}_{safe_name}_{reference}.pdf"
    return {
        "bytes": bytes(out),
        "filename": filename,
        "mime_type": "application/pdf",
        "reference": reference,
        "title": BUSINESS_DOCUMENT_TYPES[doc_type],
    }


def _business_doc_response(document):
    response = Response(document["bytes"], mimetype="application/pdf")
    response.headers["Content-Disposition"] = (
        f'attachment; filename="{document["filename"]}"'
    )
    response.headers["Cache-Control"] = "no-store, private"
    return response


