def get_payment_totals_by_lead(lead_ids):
    if not lead_ids:
        return {}

    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT lead_id, currency, COALESCE(SUM(amount), 0), MAX(received_at)
                FROM lead_payments
                WHERE lead_id = ANY(%s)
                GROUP BY lead_id, currency
                """,
                (list(lead_ids),)
            )
            rows = cur.fetchall()

    result = {}
    for lead_id, currency, total, latest_at in rows:
        result.setdefault(lead_id, {})[currency] = {
            "total": Decimal(total),
            "latest_at": latest_at,
        }
    return result


def get_customer_payments(lead_ids, limit=100):
    if not lead_ids:
        return []

    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT
                    p.id, p.lead_id, p.amount, p.currency, p.payment_method,
                    p.reference, p.payment_note, p.received_at, l.service
                FROM lead_payments p
                JOIN leads l ON l.id = p.lead_id
                WHERE p.lead_id = ANY(%s)
                ORDER BY p.received_at DESC, p.id DESC
                LIMIT %s
                """,
                (list(lead_ids), int(limit))
            )
            rows = cur.fetchall()

    return [
        {
            "id": row[0],
            "lead_id": row[1],
            "amount": Decimal(row[2]),
            "currency": row[3],
            "payment_method": row[4],
            "reference": row[5] or "",
            "payment_note": row[6] or "",
            "received_at": row[7],
            "service": canonicalize_service(row[8]),
        }
        for row in rows
    ]


def _lead_payment_snapshot(lead, payment_totals):
    currency = lead.get("value_currency") or "MWK"
    total = Decimal("0")
    latest_at = None
    currency_data = (payment_totals.get(lead["id"]) or {}).get(currency)
    if currency_data:
        total = Decimal(currency_data["total"])
        latest_at = currency_data["latest_at"]

    estimated = lead.get("estimated_value")
    estimated = Decimal(estimated) if estimated is not None else None

    balance = None
    overpayment = Decimal("0")
    if estimated is not None:
        raw_balance = estimated - total
        if raw_balance > 0:
            balance = raw_balance
        else:
            balance = Decimal("0")
            if raw_balance < 0:
                overpayment = -raw_balance

    if total <= 0:
        status = "NOT_PAID"
        status_label = "Not paid"
    elif estimated is None:
        status = "RECEIVED_UNPRICED"
        status_label = "Payment received"
    elif total < estimated:
        status = "PART_PAID"
        status_label = "Part paid"
    else:
        status = "PAID"
        status_label = "Paid"

    return {
        "paid_total": total,
        "paid_label": _format_crm_amount(total, currency) if total else "",
        "balance": balance,
        "balance_label": (
            _format_crm_amount(balance, currency) if balance is not None else ""
        ),
        "overpayment": overpayment,
        "overpayment_label": (
            _format_crm_amount(overpayment, currency) if overpayment else ""
        ),
        "payment_status": status,
        "payment_status_label": status_label,
        "latest_payment_at": latest_at,
    }



def _duplicate_service_groups(leads):
    groups = {}
    for lead in leads or []:
        if lead.get("merged_into_lead_id") is not None:
            continue
        service = canonicalize_service(lead.get("service"))
        groups.setdefault(service, []).append(lead)

    duplicates = []
    for service, items in groups.items():
        if len(items) < 2:
            continue
        duplicates.append({
            "service": service,
            "count": len(items),
            "lead_ids": [item["id"] for item in items],
        })

    duplicates.sort(key=lambda item: (-item["count"], item["service"].casefold()))
    return duplicates


def consolidate_customer_duplicate_service(customer_number, requested_service):
    """
    Non-destructive consolidation:
    - chooses the best current record as the primary lead;
    - keeps every original duplicate row in PostgreSQL;
    - marks duplicates as merged/archived so normal lead views ignore them;
    - preserves their notes/activity in customer CRM history;
    - fills only empty/default fields on the primary record.
    """
    canonical_service = canonicalize_service(requested_service)

    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT
                    id, customer_name, service, summary, handover_reason,
                    status, priority, follow_up_at, follow_up_notified_at,
                    follow_up_notification_claimed_at,
                    follow_up_notification_error,
                    estimated_value, value_currency, quote_status,
                    quote_reference, created_at, updated_at
                FROM leads
                WHERE customer_number = %s
                  AND merged_into_lead_id IS NULL
                ORDER BY
                    CASE
                        WHEN status = 'CONTACTED' THEN 0
                        WHEN status = 'NEW' THEN 1
                        ELSE 2
                    END,
                    updated_at DESC,
                    id DESC
                FOR UPDATE
                """,
                (customer_number,)
            )
            rows = cur.fetchall()

            matches = [
                row for row in rows
                if canonicalize_service(row[2]).casefold()
                   == canonical_service.casefold()
            ]

            if len(matches) < 2:
                return {
                    "merged_count": 0,
                    "target_id": matches[0][0] if matches else None,
                    "service": canonical_service,
                }

            target = list(matches[0])
            sources = [list(row) for row in matches[1:]]
            target_id = target[0]

            # Fill only gaps/defaults. Never overwrite established current data.
            def first_nonempty(index):
                for row in sources:
                    value = row[index]
                    if value not in (None, ""):
                        return value
                return None

            customer_name = target[1] or first_nonempty(1)
            summary = target[3] or first_nonempty(3)
            handover_reason = target[4] or first_nonempty(4)

            follow_up_at = target[7]
            follow_up_notified_at = target[8]
            follow_up_claimed_at = target[9]
            follow_up_error = target[10]
            if follow_up_at is None and target[5] != "CLOSED":
                for row in sources:
                    if row[7] is not None:
                        follow_up_at = row[7]
                        follow_up_notified_at = row[8]
                        follow_up_claimed_at = row[9]
                        follow_up_error = row[10]
                        break

            estimated_value = target[11]
            value_currency = target[12] or "MWK"
            if estimated_value is None:
                for row in sources:
                    if row[11] is not None:
                        estimated_value = row[11]
                        value_currency = row[12] or "MWK"
                        break

            quote_status = target[13] or "NOT_STARTED"
            if quote_status == "NOT_STARTED":
                for row in sources:
                    source_status = row[13] or "NOT_STARTED"
                    if source_status != "NOT_STARTED":
                        quote_status = source_status
                        break

            quote_reference = target[14] or first_nonempty(14)

            cur.execute(
                """
                UPDATE leads
                SET customer_name = %s,
                    service = %s,
                    summary = %s,
                    handover_reason = %s,
                    follow_up_at = %s,
                    follow_up_notified_at = %s,
                    follow_up_notification_claimed_at = %s,
                    follow_up_notification_error = %s,
                    estimated_value = %s,
                    value_currency = %s,
                    quote_status = %s,
                    quote_reference = %s,
                    updated_at = NOW()
                WHERE id = %s
                """,
                (
                    customer_name,
                    canonical_service,
                    summary,
                    handover_reason,
                    follow_up_at,
                    follow_up_notified_at,
                    follow_up_claimed_at,
                    follow_up_error,
                    estimated_value,
                    value_currency,
                    quote_status,
                    quote_reference,
                    target_id,
                )
            )

            source_ids = [row[0] for row in sources]

            # Preserve the payment ledger by attaching historical transactions
            # to the surviving current lead before archiving duplicate lead rows.
            cur.execute(
                """
                UPDATE lead_payments
                SET lead_id = %s
                WHERE lead_id = ANY(%s)
                """,
                (target_id, source_ids)
            )

            cur.execute(
                """
                UPDATE leads
                SET merged_into_lead_id = %s,
                    merged_at = NOW(),
                    updated_at = NOW()
                WHERE id = ANY(%s)
                  AND merged_into_lead_id IS NULL
                """,
                (target_id, source_ids)
            )
            merged_count = cur.rowcount

            if merged_count:
                ids_label = ", ".join(f"#{lead_id}" for lead_id in source_ids)
                _activity_insert(
                    cur,
                    target_id,
                    "MERGE",
                    (
                        f"Consolidated {merged_count} duplicate historical "
                        f"{canonical_service} lead record(s). Original lead IDs "
                        f"retained as merged history: {ids_label}."
                    ),
                )

        conn.commit()

    print(
        f"LEAD DUPLICATES CONSOLIDATED: customer={customer_number} "
        f"service={canonical_service} target={target_id} merged={merged_count}",
        flush=True,
    )
    return {
        "merged_count": merged_count,
        "target_id": target_id,
        "service": canonical_service,
    }



def get_customer_crm_profile(customer_number):
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT
                    id, customer_number, customer_name, service, summary,
                    handover_reason, status, priority, follow_up_at,
                    follow_up_notified_at, estimated_value, value_currency,
                    quote_status, quote_reference, created_at, updated_at,
                    merged_into_lead_id, merged_at
                FROM leads
                WHERE customer_number = %s
                ORDER BY created_at DESC, id DESC
                """,
                (customer_number,)
            )
            lead_rows = cur.fetchall()

            if not lead_rows:
                return None

            lead_ids = [row[0] for row in lead_rows]

            cur.execute(
                """
                SELECT
                    a.lead_id, a.activity_type, a.description, a.created_at,
                    l.service
                FROM lead_activity a
                JOIN leads l ON l.id = a.lead_id
                WHERE a.lead_id = ANY(%s)
                ORDER BY a.created_at DESC, a.id DESC
                LIMIT 150
                """,
                (lead_ids,)
            )
            activity_rows = cur.fetchall()

            cur.execute(
                """
                SELECT
                    n.lead_id, n.note_text, n.created_at, l.service
                FROM lead_notes n
                JOIN leads l ON l.id = n.lead_id
                WHERE n.lead_id = ANY(%s)
                ORDER BY n.created_at DESC, n.id DESC
                LIMIT 150
                """,
                (lead_ids,)
            )
            note_rows = cur.fetchall()

    all_leads = []
    for row in lead_rows:
        all_leads.append({
            "id": row[0],
            "customer_number": row[1],
            "customer_name": row[2],
            "service": canonicalize_service(row[3]),
            "summary": row[4],
            "handover_reason": row[5],
            "status": row[6],
            "priority": row[7] or "NORMAL",
            "follow_up_at": row[8],
            "follow_up_notified_at": row[9],
            "estimated_value": row[10],
            "value_currency": row[11] or "MWK",
            "quote_status": row[12] or "NOT_STARTED",
            "quote_reference": row[13] or "",
            "created_at": row[14],
            "updated_at": row[15],
            "merged_into_lead_id": row[16],
            "merged_at": row[17],
        })

    active_leads = [
        lead for lead in all_leads
        if lead["merged_into_lead_id"] is None
    ]
    archived_leads = [
        lead for lead in all_leads
        if lead["merged_into_lead_id"] is not None
    ]

    timeline = []
    for lead in all_leads:
        if lead["merged_into_lead_id"] is None:
            description = f"{lead['service']} lead created."
        else:
            description = (
                f"Historical {lead['service']} lead #{lead['id']} retained "
                f"after consolidation into lead #{lead['merged_into_lead_id']}."
            )
        timeline.append({
            "kind": "LEAD_CREATED",
            "description": description,
            "created_at": lead["created_at"],
            "service": lead["service"],
        })

    for lead_id, activity_type, description, created_at, service in activity_rows:
        timeline.append({
            "kind": activity_type,
            "description": description,
            "created_at": created_at,
            "service": canonicalize_service(service),
        })

    for lead_id, note_text, created_at, service in note_rows:
        timeline.append({
            "kind": "NOTE",
            "description": f"Internal note: {note_text}",
            "created_at": created_at,
            "service": canonicalize_service(service),
        })

    payments = get_customer_payments(lead_ids, limit=100)
    for payment in payments:
        method_label = PAYMENT_METHODS.get(
            payment["payment_method"],
            payment["payment_method"].replace("_", " ").title(),
        )
        description = (
            f"Payment received: {_format_crm_amount(payment['amount'], payment['currency'])} "
            f"via {method_label}."
        )
        if payment["reference"]:
            description += f" Reference: {payment['reference']}."
        timeline.append({
            "kind": "PAYMENT",
            "description": description,
            "created_at": payment["received_at"],
            "service": payment["service"],
        })

    timeline.sort(key=lambda item: item["created_at"], reverse=True)

    return {
        "leads": active_leads,
        "timeline": timeline[:200],
        "payments": payments,
        "archived_merged_count": len(archived_leads),
        "duplicate_groups": _duplicate_service_groups(active_leads),
    }


def _format_crm_amount(amount, currency):
    if amount is None:
        return ""
    amount = Decimal(amount)
    if amount == amount.to_integral():
        number = f"{amount:,.0f}"
    else:
        number = f"{amount:,.2f}"
    return f"{currency} {number}"



def get_all_leads():
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("""
                SELECT
                    id,
                    customer_number,
                    customer_name,
                    service,
                    summary,
                    handover_reason,
                    status,
                    priority,
                    follow_up_at,
                    follow_up_notified_at,
                    estimated_value,
                    value_currency,
                    quote_status,
                    quote_reference,
                    created_at,
                    updated_at
                FROM leads
                WHERE merged_into_lead_id IS NULL
                ORDER BY
                    CASE
                        WHEN status <> 'CLOSED'
                             AND follow_up_at IS NOT NULL
                             AND follow_up_at <= NOW() THEN 0
                        WHEN status = 'NEW' THEN 1
                        WHEN priority = 'URGENT' THEN 2
                        WHEN priority = 'HIGH' THEN 3
                        WHEN status = 'CONTACTED' THEN 4
                        WHEN status = 'CLOSED' THEN 6
                        ELSE 5
                    END,
                    COALESCE(follow_up_at, updated_at) ASC,
                    updated_at DESC
            """)
            return cur.fetchall()


def get_lead_counts():
    counts = {
        "ALL": 0,
        "NEW": 0,
        "CONTACTED": 0,
        "CLOSED": 0
    }

    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("""
                SELECT status, COUNT(*)
                FROM leads
                WHERE merged_into_lead_id IS NULL
                GROUP BY status
            """)
            for status, count in cur.fetchall():
                counts["ALL"] += count
                if status in counts:
                    counts[status] = count

    return counts



def _crm_amount_lines(amounts):
    """Return stable per-currency labels without unsafe FX aggregation."""
    order = ["MWK", "USD", "ZAR", "EUR", "GBP"]
    lines = []
    for currency in order:
        amount = amounts.get(currency)
        if amount is None:
            continue
        amount = Decimal(amount)
        if amount == 0:
            continue
        lines.append({
            "currency": currency,
            "amount": amount,
            "label": _format_crm_amount(amount, currency),
        })
    for currency in sorted(set(amounts) - set(order)):
        amount = Decimal(amounts[currency])
        if amount:
            lines.append({
                "currency": currency,
                "amount": amount,
                "label": _format_crm_amount(amount, currency),
            })
    return lines



