@app.route("/tasks/followup-reminders", methods=["POST"])
def follow_up_reminder_task():
    if not FOLLOWUP_CRON_SECRET:
        print("FOLLOW-UP REMINDER TASK BLOCKED: FOLLOWUP_CRON_SECRET missing", flush=True)
        return Response(
            json.dumps({"ok": False, "error": "task not configured"}),
            status=503,
            mimetype="application/json",
        )

    supplied = request.headers.get("X-IBROWS-CRON-SECRET", "")
    if not supplied or not hmac.compare_digest(supplied, FOLLOWUP_CRON_SECRET):
        return Response(
            json.dumps({"ok": False, "error": "unauthorized"}),
            status=401,
            mimetype="application/json",
        )

    follow_up_result = process_due_follow_up_reminders(limit=20)
    invoice_result = process_due_invoice_reminders(limit=20)
    result = {
        "ok": True,
        "follow_up": follow_up_result,
        "invoice": invoice_result,
    }
    return Response(
        json.dumps(result, separators=(",", ":")),
        mimetype="application/json",
    )



@app.route("/admin/login", methods=["GET", "POST"])
def admin_login():

    if session.get("admin_authenticated"):
        return redirect(url_for("admin_leads"))

    error = None
    csrf_token = get_csrf_token()

    if request.method == "POST":

        validate_csrf()

        client_key = _login_client_key()
        if _login_is_locked(client_key):
            error = "Too many sign-in attempts. Please wait 15 minutes and try again."
            return render_template_string(
                LOGIN_TEMPLATE,
                error=error,
                csrf_token=get_csrf_token()
            ), 429

        username = request.form.get("username", "")
        password = request.form.get("password", "")

        username_ok = (
            ADMIN_USERNAME
            and secrets.compare_digest(
                username,
                ADMIN_USERNAME
            )
        )

        password_ok = (
            ADMIN_PASSWORD
            and secrets.compare_digest(
                password,
                ADMIN_PASSWORD
            )
        )

        if username_ok and password_ok:
            _clear_failed_logins(client_key)
            session.clear()
            session.permanent = True
            session["admin_authenticated"] = True
            session["csrf_token"] = secrets.token_urlsafe(32)

            return redirect(url_for("admin_leads"))

        _record_failed_login(client_key)
        error = "Incorrect username or password."

    return render_template_string(
        LOGIN_TEMPLATE,
        error=error,
        csrf_token=csrf_token
    )


